import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Kimi 对话与 Agent","description":"写给谁：在选月之暗面产品面的前端工程师。你需要浏览器或 Kimi App，不需要仓库。","frontmatter":{"title":"Kimi 对话与 Agent","description":"写给谁：在选月之暗面产品面的前端工程师。你需要浏览器或 Kimi App，不需要仓库。","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/kimi/kimi.md","filePath":"zh/products/kimi/kimi.md","lastUpdated":1787110548000}'),i={name:"zh/products/kimi/kimi.md"};function l(n,t,s,h,m,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="kimi-对话与-agent" tabindex="-1">Kimi 对话与 Agent <a class="header-anchor" href="#kimi-对话与-agent" aria-label="Permalink to &quot;Kimi 对话与 Agent&quot;">​</a></h1><blockquote><p><strong>Kimi</strong> 是月之暗面的一站式 AI 工作台。官方定义（<a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">zh-cn/products</a>）： 「从深度研究、幻灯片到表格、文档与网站，Kimi 内置强大的 Agent 能力。」</p><p><strong>Kimi Agent</strong> 的官方定义（<a href="https://www.kimi.com/zh-hans/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent 概览</a>）： 「Kimi Agent 是一款可端到端处理复杂任务的自主 AI 助手。它由 Kimi K3 驱动，可调用 20 多种工具来构建网站、生成文档、分析数据等。」</p><p>本页只根据 kimi.com、产品页和帮助中心写入口与步骤。它<strong>不是</strong> Kimi Code——编码 CLI 见 <a href="/zh/products/kimi-code/">Kimi Code</a>。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 在选 Kimi 产品面的前端工程师。你需要浏览器或 Kimi App，不需要 checkout。</p><p><strong>目标：</strong> 打开 kimi.com，分清对话 / Agent / Swarm / Claw，跑完第一次 Agent 任务，知道额度从哪张官方表查。</p><p><strong>非目标：</strong> Kimi Code 安装；臆造人民币价；把 Moderato 写成 Go；讲解模型内部。机制见 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>。</p><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>一张工作台，几个官方客户端：</p><table tabindex="0"><thead><tr><th>客户端</th><th>官方入口</th></tr></thead><tbody><tr><td>Web</td><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td></tr><tr><td>Agent</td><td><a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a></td></tr><tr><td>Agent Swarm</td><td><a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a></td></tr><tr><td>Kimi Claw</td><td><a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></td></tr><tr><td>App</td><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a> 页脚「扫码下载 Kimi App」</td></tr></tbody></table><p>首页侧栏抄官方标签（<a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a>）：<strong>Plugins、Scheduled Tasks、Slides、Swarm、Deep Research、Docs、Websites、Sheets、Design</strong>，以及 <strong>Kimi Work / Kimi Code / Kimi Claw</strong>。新对话快捷键首页写的是 <strong>⌘K</strong>。</p><p>Agent 核心能力（<a href="https://www.kimi.com/zh-cn/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent 概览</a>）：</p><table tabindex="0"><thead><tr><th>能力</th><th>官方说明</th></tr></thead><tbody><tr><td>网站（Websites）</td><td>生成并部署响应式网站 / 应用</td></tr><tr><td>文档（Docs）</td><td>Word、PDF、Markdown 等</td></tr><tr><td>表格（Sheets）</td><td>Excel / CSV，官方写可整理 1000 行 Excel</td></tr><tr><td>幻灯片（Slides）</td><td>自动生成 PPT</td></tr><tr><td>深度研究（Deep Research）</td><td>万字级研究报告</td></tr><tr><td>Agent Swarm</td><td>最多 300 个子代理并行，超过 4,000 次工具调用</td></tr><tr><td>Kimi Claw</td><td>零部署云端自动化；帮助中心写内置 5,000+ 技能库（ClawHub）</td></tr></tbody></table><p>工作步骤（同一页）：任务规划 → 工具调用（20 多种）→ 自主执行 → 异常处理 → 成果交付。</p><h2 id="第一次-打开对话" tabindex="-1">第一次：打开对话 <a class="header-anchor" href="#第一次-打开对话" aria-label="Permalink to &quot;第一次：打开对话&quot;">​</a></h2><ol><li>打开 <a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a>，登录。未登录时侧栏写「Log in to sync chat history」。</li><li>在输入框提问。首页文案：「Ask anything, or task an agent...」</li><li>聊天额度口径以会员页为准：官方原文「在聊天中，K2.6 对所有用户免费，且不消耗额度」（<a href="https://www.kimi.com/zh-hans/help/membership/membership-overview" target="_blank" rel="noreferrer">会员概览</a>）。</li></ol><p>需要持久上下文时建 <strong>Project</strong>，不要每轮重贴同一批文件。见下一节。</p><h2 id="第一次-跑一个-agent-任务" tabindex="-1">第一次：跑一个 Agent 任务 <a class="header-anchor" href="#第一次-跑一个-agent-任务" aria-label="Permalink to &quot;第一次：跑一个 Agent 任务&quot;">​</a></h2><p>官方入口（<a href="https://www.kimi.com/zh-cn/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent 概览</a>）：</p><ul><li><strong>网页：</strong> <a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">https://www.kimi.com/agent</a></li><li><strong>手机 / 平板：</strong> 打开 Kimi App，在对话框上方的<strong>模型切换按钮</strong>里选 <strong>K3</strong> 或 <strong>K3 集群</strong></li></ul><p>步骤（抄官方）：</p><ol><li>清晰描述任务并发送。官方例子：「帮我创建一个在线投票工具的网站代码」、「分析 2025 年 AI 芯片行业的竞争格局」。</li><li>看执行过程：推理链路、工具、访问的网址、中间代码。</li><li>任务完成后下载或分享：代码项目、文件夹、数据分析、Word / PDF / PPT。</li></ol><p>适用场景（官方列表）：网站开发、内容生成、合同比对 / 长文档翻译、数据分析、PPT、文档互转。</p><h2 id="agent-swarm" tabindex="-1">Agent Swarm <a class="header-anchor" href="#agent-swarm" aria-label="Permalink to &quot;Agent Swarm&quot;">​</a></h2><p>官方定义（<a href="https://www.kimi.com/zh-hans/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a>）：横向扩展，协调最多 <strong>300</strong> 个子 Agent，无需预设角色或手工编排。相比单 Agent，官方写任务完成速度约提升 <strong>4.5 倍</strong>；单任务可超过 <strong>4,000</strong> 次工具调用。当前由 <strong>Kimi K3（K3 Swarm）</strong> 驱动。</p><p><strong>入口：</strong></p><ul><li>Web：<a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">https://www.kimi.com/agent-swarm</a></li><li>移动端：Kimi App 模型切换选 <strong>K3 Swarm</strong></li></ul><p><strong>资格：</strong> 面向 <strong>Moderato、Allegretto、Allegro、Vivace</strong> 会员。官方写：相比标准 Agent，此类任务会消耗明显更多额度。页上的 <strong>[Beta]</strong> 表示初期仅面向少量用户。</p><p>步骤（官方）：描述任务 → 看子 Agent 并行 → 收交付物 → 后续轮次会在对话与 Agent 之间自动调度，无需手动切换。</p><p>适合：大规模检索、批量下载、100+ 文档、超长写作、复杂编程、Office 自动化。不适合一句就能答完的闲聊。</p><h2 id="kimi-claw" tabindex="-1">Kimi Claw <a class="header-anchor" href="#kimi-claw" aria-label="Permalink to &quot;Kimi Claw&quot;">​</a></h2><p>官方定位（<a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a>）：通过 Kimi Claw 在 Kimi 里和 <strong>OpenClaw</strong> 对话。OpenClaw 是「有鲜明个性和长期记忆」的助手。</p><p><strong>一键部署（云端）：</strong></p><ol><li>登录 <a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></li><li>点 <strong>Create</strong> Kimi Claw</li><li>等系统自动配置（官方：通常几分钟）</li><li>改昵称；在 <strong>Settings → Chat channels</strong> 配微信 / 飞书 / 企微等</li></ol><p>官方约束：一键部署仅 <strong>Allegretto 及以上</strong>。默认配置 <strong>Kimi K2.6</strong>，并挂到你的<strong>会员额度</strong>，同时打开 Kimi Web Search。可部署到飞书、企微、微博等。</p><p><strong>接入已有 OpenClaw：</strong> Claw 页选 <strong>Link existing OpenClaw</strong>，在跑 OpenClaw 的设备上按说明装 Kimi 插件。</p><p><strong>Claw 群聊</strong>（<a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">group-chat</a>）：侧栏 <strong>+</strong> → <strong>Start Group Chat</strong>，填 Group Name 与 Group Goal，选已连接的 Claw。Kimi 自动指定 <strong>Conductor</strong>。主聊天发 <code>/stop</code> 可强制打断。群规则用自然语言让 Kimi 改。Allegretto 起；会员表写 10 个群聊。</p><p>把 Claw 默认模型切到 K3 的命令在官方 Claw 页，路径是本机 <code>/root/.openclaw/openclaw.json</code>（或你的实际安装路径）。那是 <strong>OpenClaw 配置</strong>，不是 kimi.com 输入框命令。需要时打开 <a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a> 抄原文，改前先备份。</p><h2 id="projects、记忆、skills、插件、定时任务" tabindex="-1">Projects、记忆、Skills、插件、定时任务 <a class="header-anchor" href="#projects、记忆、skills、插件、定时任务" aria-label="Permalink to &quot;Projects、记忆、Skills、插件、定时任务&quot;">​</a></h2><p>这些是工作台横切能力，官方分类在 <a href="https://www.kimi.com/help/features" target="_blank" rel="noreferrer">Features</a>。</p><h3 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>：把参考文件、对话、项目指令放在一起。侧栏 <strong>Projects</strong> 旁的 <strong>+</strong>，或首页选择器 <strong>+ New project</strong>。名称 1–50 字符。</p><ul><li>项目内对话可用 <strong>项目文件、项目指令、plugins、Skills、Goal</strong>，并可换模型。</li><li>单文件 ≤ <strong>100 MB</strong>，最多 <strong>50</strong> 个文件；模型按需读取，不是每轮灌全文。</li><li>删除项目会<strong>永久删掉</strong>其对话、文件和指令，不可恢复。</li><li>上下文：system prompt + 全局主记忆 + 项目指令 + 按需文件。</li><li><strong>Kimi Work 里的 Projects 与这里不通、不共享数据。</strong></li></ul><h3 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/memory-space" target="_blank" rel="noreferrer">Memory space</a>：跨会话记偏好。官方说不会记住未授权的隐私（健康、密码、地址），除非你明确要求。管理入口：<strong>Settings → Personalization → Memory Space</strong>。可以说「记住… / 忘掉… / 你现在记得我什么」。官方：记忆不用于模型训练，可随时关或清。</p><h3 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">What are Skills?</a>：可复用知识包。输入框键入 <strong><code>/</code></strong> 选技能，或让 Kimi 自动触发。可用 <strong><code>/skill-creator</code></strong> 对话生成。官方技能例子：<code>docx</code>、<code>deep-research</code>；推荐例子：<code>sop-writer</code>、<code>event-etf-study</code>。</p><h3 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a>：接外部服务。可用范围：模型切到 <strong>K3</strong> 或 <strong>K3 Swarm</strong>，以及 Deep Research / Websites / PPT。<strong>Kimi Claw 和 Kimi Plus 对话尚不支持。</strong> 入口：侧栏 <strong>Plugins</strong>、输入框 <strong>+</strong>、或 <strong><code>/</code></strong>。部分要 OAuth。未登录不能装。部分插件按实际调用扣会员额度。</p><h3 id="定时任务" tabindex="-1">定时任务 <a class="header-anchor" href="#定时任务" aria-label="Permalink to &quot;定时任务&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a>：在 <strong>Kimi</strong> 和 <strong>Kimi Work</strong> 都有。侧栏「Create scheduled task」，或在对话里用自然语言让它建。周期：daily / weekly / monthly / 一次性。云端任务不用开着客户端。Kimi Work <strong>本地</strong>任务要桌面端开着，关掉期间错过的不会补跑。跑完可在结果对话换模型继续问，并用 <code>/</code> 调插件和 Skills。</p><p>官方提示模板：At [time], do [task], output as [format], and follow [constraints]。</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>官方出现位置：</p><ul><li>会员对比表有 <strong>Goal Mode / 目标模式</strong>：Moderato 为 —，<strong>Allegretto / Allegro / Vivace</strong> 为 ✅（<a href="https://www.kimi.com/zh-hans/help/membership/membership-overview" target="_blank" rel="noreferrer">会员概览</a>）。</li><li>项目对话「use plugins, Skills, and Goal」（<a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>）。</li></ul><p>帮助中心没有单独的「kimi.com Goal 产品页」。Kimi Work 另有 Goal Mode（<a href="https://www.kimi.com/help/kimi-work/overview" target="_blank" rel="noreferrer">Work overview</a>）。Kimi Code 的 <code>/goal</code> 是 CLI，<strong>不要</strong>在 kimi.com 输入框当命令用。</p><h2 id="会员与额度" tabindex="-1">会员与额度 <a class="header-anchor" href="#会员与额度" aria-label="Permalink to &quot;会员与额度&quot;">​</a></h2><p><a href="https://www.kimi.com/zh-hans/help/membership/membership-overview" target="_blank" rel="noreferrer">会员概览</a>（2026-08-19 打开）：</p><ul><li>四档：<strong>Moderato $19/月、Allegretto $39/月、Allegro $99/月、Vivace $199/月</strong>。</li><li><strong>所有会员功能共用一个额度池</strong>（网站部署、Deep Research、幻灯片、Kimi Code、Kimi Work、Kimi Claw、K3、K3 Swarm）。按 token 计量。</li><li>聊天里 <strong>K2.6 免费且不耗额度</strong>。</li><li>额度每个计费周期重置。年付官方写最多可省 <strong>$480/年</strong>。</li><li>Kimi Code <strong>另外</strong>有 5 小时 / 每周速率限制，不影响其它会员功能。</li></ul><p>同一页第二张表还写了：Agent 并发、K3 超长对话（Allegro / Vivace，最高 100 万 tokens）、定时任务数、项目数、Swarm 并发子任务、Goal、Claw、Claw 群聊等。完整数字进 <a href="./kimi-cheatsheet.html">速查表</a>。</p><p><strong>两套官方套餐名：</strong> Projects / Scheduled Tasks 页使用 <strong>Free / Go / Pro / Max / Ultra</strong>，且数字与会员概览不完全相同。本页<strong>不以意译对齐</strong>。查价与会员权益以会员概览为准；查项目数 / 定时任务上限时打开对应功能页，冲突先看该功能页并链会员页。</p><p>本页<strong>不</strong>写人民币价。以你账号里的会员 / 用量页为准。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li>把对话里出的网站代码当成已经改好了本地仓库。要改 checkout，去 <a href="/zh/products/kimi-code/">Kimi Code</a>。</li><li>没开会员就进 <code>kimi.com/agent-swarm</code> 或 <code>kimi.com/bot</code>，对照会员表：Swarm 要 Moderato+，一键 Claw 要 Allegretto+。</li><li>把 Kimi Work 桌面项目和 kimi.com Projects 当成同步盘。</li><li>把 Kimi Code <code>/goal</code> 打进网页输入框。</li><li>用一份「应该是」的套餐对照表合并 Moderato 和 Go。</li><li>在 Claw / Kimi Plus 对话里找网页插件——官方写尚未支持。</li><li>指望 Kimi Work 本地定时任务在关机后补跑。</li></ul><h2 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>用来干什么</th></tr></thead><tbody><tr><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td><td>产品本体</td></tr><tr><td><a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">zh-cn/products</a></td><td>一级产品家族</td></tr><tr><td><a href="https://www.kimi.com/zh-cn/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent 概览</a></td><td>Agent 入口与步骤</td></tr><tr><td><a href="https://www.kimi.com/zh-hans/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a></td><td>Swarm 入口与限制</td></tr><tr><td><a href="https://www.kimi.com/zh-hans/help/membership/membership-overview" target="_blank" rel="noreferrer">会员概览</a></td><td>套餐与额度池</td></tr><tr><td><a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a></td><td>一键部署 / 连接已有 OpenClaw</td></tr><tr><td><a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">Claw 群聊</a></td><td>Conductor、Thread、<code>/stop</code></td></tr><tr><td><a href="https://www.kimi.com/zh-hans/help" target="_blank" rel="noreferrer">帮助中心</a></td><td>分类总入口</td></tr><tr><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td><td>公司站、App 下载</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./kimi-cookbook.html">Cookbook</a></li><li><a href="./kimi-cheatsheet.html">速查表</a></li><li><a href="./kimi-glossary.html">术语表</a></li><li><a href="/zh/products/kimi-code/">Kimi Code</a></li></ul>',67)])])}const f=e(i,[["render",l]]);export{k as __pageData,f as default};
